python3 - <<'EOF'
import csv, json, glob
rows = list(csv.DictReader(open('market.csv')))
allq = set(r['qid'] for r in rows)
submitted = set()
for f in glob.glob('predictions/*.json'):
    try:
        data = json.load(open(f))
        for e in data:
            submitted.add(str(e['question_id']))
    except Exception as ex:
        print('err', f, ex)
print('Submitted so far:', len(submitted))
remaining = allq - submitted
print('Remaining:', len(remaining))
qmap = {r['qid']: (r['resolution_date'], r['title'][:90]) for r in rows}
for q in sorted(remaining, key=lambda x: qmap[x][0]):
    print(q, qmap[q][0], qmap[q][1])
EOF
